<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';$user=require_role('organization');
require_once __DIR__.'/../includes/organization_requests.php';$id=donor_donation_id();
try {$profile=organization_profile((int)$user['id']);$request=organization_request($id,(int)$profile['id']);}
catch (PDOException $exception) {error_log('Organization tracking failed. Code: '.$exception->getCode());donation_load_error();}
if (!$request) {http_response_code(404);exit('Request not found.');}
$approved=$request['request_status']==='approved';$donationStatus=donation_display_status($request);
$paused=in_array($donationStatus,['cancelled','expired'],true) || $request['task_status']==='cancelled';
$receiptSuccess=($_SESSION['receipt_success']??null)===$id;unset($_SESSION['receipt_success']);
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Track request | <?= e(APP_NAME) ?></title><link rel="stylesheet" href="<?= e(app_url('assets/css/bootstrap.min.css')) ?>"><link rel="stylesheet" href="<?= e(app_url('assets/css/style.css')) ?>"></head><body>
<?php $navigationUser=$user;require __DIR__.'/../includes/header.php'; ?><main class="container py-5" id="main-content"><div class="row g-4"><?php $organizationPage=$approved && $request['status']==='completed'?'history':'requests';require __DIR__.'/../includes/organization_sidebar.php'; ?>
<section class="col-lg-9" aria-labelledby="tracking-heading"><div class="dashboard-welcome mb-4"><a class="home-link" href="<?= e(app_url('organization/requests.php')) ?>">&larr; My requests</a><h1 class="h2 mt-3" id="tracking-heading"><?= e($request['food_name']) ?></h1><div class="dashboard-meta"><span>Request: <?= status_badge($request['request_status']) ?></span><span>Donation: <?= status_badge($donationStatus) ?></span></div></div>
<?php if ($paused): ?><div class="alert alert-warning" role="status">This donation or collection task is closed. The last recorded progress remains below.</div><?php elseif ($request['request_status']==='rejected'): ?><div class="alert alert-info" role="status">The donor rejected this request. Its history is kept here.</div><?php elseif ($request['request_status']==='cancelled'): ?><div class="alert alert-info" role="status">This request was cancelled. Its history is kept here.</div><?php endif; ?>
<?php if ($receiptSuccess): ?><div class="alert alert-success" role="status">Receipt confirmed. This donation is now completed and appears in Completed history.</div><?php endif; ?>
<?php if (can_confirm_receipt($request)): ?><section class="account-card mb-4" aria-labelledby="receipt-heading"><h2 class="h5" id="receipt-heading">Confirm food receipt</h2><p>The volunteer has recorded delivery. Confirm after your organization receives the food. This completes the donation.</p><form method="post" action="<?= e(app_url('organization/confirm_receipt.php?id='.$id)) ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="form-check mb-3"><input class="form-check-input" type="checkbox" name="confirm_received" value="yes" id="confirm-received" required><label class="form-check-label" for="confirm-received">My organization has received this food.</label></div><button class="btn btn-success" type="submit">Confirm receipt</button></form></section><?php endif; ?>
<section class="account-card mb-4" aria-labelledby="progress-heading"><h2 class="h5 mb-4" id="progress-heading"><?= $approved?'Collection and delivery progress':'Request progress' ?></h2>
<?php if ($approved): ?><ol class="request-timeline"><?php foreach (organization_tracking_steps($request) as [$label,$recorded]): ?><li class="<?= $recorded!==null?'is-recorded':'' ?>"><span class="timeline-dot" aria-hidden="true"></span><div><strong><?= e($label) ?></strong><span><?= $recorded!==null?e(dashboard_date($recorded)):'Not recorded yet' ?></span></div></li><?php endforeach; ?></ol>
<?php else: ?><dl class="row account-details mb-0"><dt class="col-sm-4">Request submitted</dt><dd class="col-sm-8"><?= e(dashboard_date($request['created_at'])) ?></dd><dt class="col-sm-4">Donor decision</dt><dd class="col-sm-8"><?= $request['decided_at']!==null?e(dashboard_date($request['decided_at'])):'Awaiting donor review' ?></dd></dl><?php endif; ?>
<p class="form-text mt-3 mb-0">Times use Sri Lanka time and reflect recorded updates.</p></section>
<section class="account-card mb-4"><h2 class="h5">Your request details</h2><dl class="row account-details mt-4"><dt class="col-sm-4">Quantity</dt><dd class="col-sm-8"><?= e(rtrim(rtrim($request['quantity'],'0'),'.').' '.$request['quantity_unit']) ?></dd><dt class="col-sm-4">Delivery address</dt><dd class="col-sm-8 donation-description"><?= e($request['delivery_address']) ?></dd><dt class="col-sm-4">Collection deadline</dt><dd class="col-sm-8"><?= e(dashboard_date($request['deadline_at'])) ?></dd></dl><h3 class="h6">Your message</h3><p class="donation-description"><?= e($request['message']??'No message provided.') ?></p><a class="home-link" href="<?= e(app_url('organization/donation.php?id='.$request['donation_id'])) ?>">View food details &rarr;</a></section>
<?php if ($approved): ?><section class="account-card"><h2 class="h5">Collection contacts</h2><dl class="row account-details mt-4"><dt class="col-sm-4">Donor</dt><dd class="col-sm-8"><?= e($request['donor_name']) ?></dd><dt class="col-sm-4">Donor phone</dt><dd class="col-sm-8"><?= e($request['donor_phone']) ?></dd><dt class="col-sm-4">Donor email</dt><dd class="col-sm-8"><?= e($request['donor_email']) ?></dd><dt class="col-sm-4">Pickup location</dt><dd class="col-sm-8 donation-description"><?= e($request['pickup_location']) ?></dd>
<?php if ($request['task_id']!==null): ?><dt class="col-sm-4">Task status</dt><dd class="col-sm-8"><?= status_badge($request['task_status']) ?></dd><dt class="col-sm-4">Volunteer</dt><dd class="col-sm-8"><?= e($request['volunteer_name']??'Not available') ?></dd><dt class="col-sm-4">Volunteer phone</dt><dd class="col-sm-8"><?= e($request['volunteer_phone']??'Not available') ?></dd><dt class="col-sm-4">Task accepted</dt><dd class="col-sm-8"><?= $request['accepted_at']!==null?e(dashboard_date($request['accepted_at'])):'Not recorded yet' ?></dd><?php else: ?><dt class="col-sm-4">Volunteer</dt><dd class="col-sm-8">Awaiting administrator assignment</dd><?php endif; ?></dl></section><?php endif; ?>
</section></div></main><?php require __DIR__.'/../includes/footer.php'; ?></body></html>
